import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { applyStaticShell, loadShell } from './shell-inject.mjs';

// Bakes the shared site shell into every hand-authored content page's delivered
// HTML — the guide pages and the legal/info pages — so the shell no longer has
// to be constructed at runtime by layout.js (which is what made these pages
// jump on load). Idempotent via HTML markers; re-run whenever the shell markup
// in layout.js changes.
//
// Conversion pages are generated by generate-conversion-pages.mjs, which emits
// the same shell inline, so they are not processed here.

const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const shell = loadShell();

// Hand-authored pages that rely on the shell. Guides are the whole guides/
// folder; the legal/info pages are individually listed at the repo root.
const legalPages = ['about.html', 'privacy.html', 'terms.html', 'contact.html', 'accessibility.html'];

const targets = [
  ...fs.readdirSync(path.join(rootDir, 'guides'))
    .filter((f) => f.endsWith('.html'))
    .map((f) => path.join('guides', f)),
  ...legalPages
];

let updated = 0;
for (const rel of targets) {
  const filePath = path.join(rootDir, rel);
  if (!fs.existsSync(filePath)) throw new Error(`generate-static-shell: expected page missing: ${rel}`);
  const html = fs.readFileSync(filePath, 'utf8');
  const next = applyStaticShell(html, shell);
  if (next !== html) updated += 1;
  fs.writeFileSync(filePath, next);
}

console.log(`Baked the static shell into ${targets.length} content pages (${updated} changed): ${fs.readdirSync(path.join(rootDir, 'guides')).filter((f) => f.endsWith('.html')).length} guides + ${legalPages.length} legal/info pages.`);
